import json

n = int(input())
for _ in range(n):
    data = json.loads(input())
    choices = data.get('choices')
    if isinstance(choices, list) and len(choices) > 0:
        message = choices[0].get('message', {})
        content = message.get('content', '')
        if content:
            print(content)
        else:
            print('[no reply]')
    else:
        print('[no reply]')
